+class SEOProStack_Media_Storage extends SEOProStack_Feature {
+    const KEY = 'media_storage';
+    const META = '_seoprostack_storage';
+    const DONE = '_seoprostack_storage_done';
+    const HOOK = 'seoprostack_media_storage_batch';
