             return;
         }
-        foreach ($removing ? self::removable($limit) : self::restorable($limit) as $id) {
+        $before = $removing ? 0 : (int) get_option(self::CURSOR . '_restore', PHP_INT_MAX);
+        $ids = $removing ? self::removable($limit) : self::restorable($limit, $before ?: PHP_INT_MAX);
+        if (!$removing && !$ids && PHP_INT_MAX !== $before) {
+            // Wrapped: start again from the newest.
+            delete_option(self::CURSOR . '_restore');
+            return;
+        }
+        foreach ($ids as $id) {
             if (!self::more_time($start, self::BUDGET)) {
                 return;
             }
             $result = $removing ? self::remove_local($id) : self::restore_attachment($id);
+            if (!$removing) {
+                update_option(self::CURSOR . '_restore', $id, false);
+            }
             if (is_wp_error($result)) {
                 update_option(self::ERROR, $result->get_error_message(), false);
-                update_option(self::LOCAL_WAIT, time() + HOUR_IN_SECONDS, false);
-                return;
