+                    update_option(self::LOCAL_WAIT, time() + HOUR_IN_SECONDS, false);
+                    return;
+                }
             }
         }
         if (!$removing && !self::restorable(1)) {
             // Every file is back: addresses follow the switch again.
             delete_option(self::FLAG);
