+        return array_map('intval', $wpdb->get_col($wpdb->prepare("SELECT DISTINCT post_id FROM {$wpdb->postmeta} WHERE meta_key IN (%s, %s) AND post_id < %d ORDER BY post_id DESC LIMIT %d", self::META, self::REMOVED, $before, $limit)));
