+        }
+        if ($hash && is_wp_error(self::download($key, $info, $client))) {
+            return 'mismatched';
+        }
+        return 'ok';
+    }
+
+    /**
+     * Distinguish absent objects from transport/permission failures.
+     *
+     * @param array|WP_Error $head HEAD result.
+     * @param array $info Recorded file.
+     * @return string
+     */
