+        if (is_string($files)) {
+            return $files;
+        }
+        if ($dry) {
+            return 'adopted';
+        }
+        $record = $old;
+        $record['files'] = $files;
+        return self::publish_handover($id, $old, $record, $generation, $source['signature']);
+    }
+
+    /**
+     * Whether both inventories have completed handover.
+     *
+     * @param array $record Inventory.
+     * @param array|null $removed Removed inventory.
+     * @return bool
+     */
