+            $target = $config['prefix'] . $info['relative'];
+            if (!isset($record['files'][$target]) || $record['files'][$target]['digest'] !== $info['digest'] || $record['files'][$target]['size'] !== $info['size']) {
+                return false;
+            }
+            $new['files'][$target] = $info;
+        }
+        update_post_meta($id, self::REMOVED, $new, $gone);
