+class SEOProStack_Vulnerability_Feed_Parser {
+
+    /** Bytes read at a time. */
+    const CHUNK = 1048576;
+
+    /** A longer record means the file is not the feed (the largest is about 160 KB). */
+    const MAX_RECORD = 8388608;
