+     */
+    private static function admin_only($page, array $screen = array()) {
+        $subjects = array($page);
+        if (!empty($screen['path'])) {
+            $subjects[] = $page . '#' . $screen['path'];
+        }
+        if (!empty($screen['tab'])) {
+            $subjects[] = $page . '/' . $screen['tab'] . (!empty($screen['section']) ? '/' . $screen['section'] : '');
